BEGIN;
DO $$ BEGIN IF current_user<>'ai_mls_production_migration_operator' THEN RAISE EXCEPTION 'REL002_R3B1_MIGRATION_OPERATOR_REQUIRED'; END IF; IF to_regnamespace('app_external_integration') IS NOT NULL THEN RAISE EXCEPTION 'REL002_R3B1_EXTERNAL_INTEGRATION_SCHEMA_ALREADY_EXISTS'; END IF; END $$;
CREATE SCHEMA app_external_integration AUTHORIZATION ai_mls_production_migration_operator;
COMMENT ON SCHEMA app_external_integration IS 'REL002-R3B1-EXTERNAL-INTEGRATION-V1|schema_version=1|contract_fingerprint=external-v1-5-tables';
CREATE TABLE app_external_integration.ext_contracts(tenant_id text NOT NULL,scope_type text NOT NULL,scope_id text NOT NULL,connector_id text NOT NULL,source_id text NOT NULL,contract_id text NOT NULL,version bigint NOT NULL CHECK(version>0 AND version<=9007199254740991),status text NOT NULL CHECK(status IN('ACTIVE','SUSPENDED')),payload_json text NOT NULL CHECK(payload_json IS JSON),PRIMARY KEY(tenant_id,scope_type,scope_id,connector_id,source_id,contract_id));
CREATE TABLE app_external_integration.ext_mappings(tenant_id text NOT NULL,scope_type text NOT NULL,scope_id text NOT NULL,connector_id text NOT NULL,source_id text NOT NULL,mapping_id text NOT NULL,contract_id text NOT NULL,provider_namespace text NOT NULL,external_object_id text NOT NULL,version bigint NOT NULL CHECK(version>0 AND version<=9007199254740991),payload_json text NOT NULL CHECK(payload_json IS JSON),PRIMARY KEY(tenant_id,scope_type,scope_id,connector_id,source_id,mapping_id),UNIQUE(tenant_id,scope_type,scope_id,connector_id,source_id,provider_namespace,external_object_id),CONSTRAINT ext_mappings_contract_fk FOREIGN KEY(tenant_id,scope_type,scope_id,connector_id,source_id,contract_id) REFERENCES app_external_integration.ext_contracts(tenant_id,scope_type,scope_id,connector_id,source_id,contract_id) ON UPDATE NO ACTION ON DELETE NO ACTION);
CREATE TABLE app_external_integration.ext_observations(tenant_id text NOT NULL,scope_type text NOT NULL,scope_id text NOT NULL,connector_id text NOT NULL,source_id text NOT NULL,provider_namespace text NOT NULL,observation_id text NOT NULL,contract_id text NOT NULL,ordinal bigint NOT NULL CHECK(ordinal>0 AND ordinal<=9007199254740991),fingerprint text NOT NULL,payload_json text NOT NULL CHECK(payload_json IS JSON),PRIMARY KEY(tenant_id,scope_type,scope_id,connector_id,source_id,provider_namespace,observation_id),UNIQUE(tenant_id,scope_type,scope_id,connector_id,source_id,contract_id,ordinal),CONSTRAINT ext_observations_contract_fk FOREIGN KEY(tenant_id,scope_type,scope_id,connector_id,source_id,contract_id) REFERENCES app_external_integration.ext_contracts(tenant_id,scope_type,scope_id,connector_id,source_id,contract_id) ON UPDATE NO ACTION ON DELETE NO ACTION);
CREATE TABLE app_external_integration.ext_idempotency(tenant_id text NOT NULL,scope_type text NOT NULL,scope_id text NOT NULL,connector_id text NOT NULL,source_id text NOT NULL,idempotency_key text NOT NULL,fingerprint text NOT NULL,result_json text NOT NULL CHECK(result_json IS JSON),PRIMARY KEY(tenant_id,scope_type,scope_id,connector_id,source_id,idempotency_key));
CREATE TABLE app_external_integration.ext_evidence(tenant_id text NOT NULL,scope_type text NOT NULL,scope_id text NOT NULL,connector_id text NOT NULL,source_id text NOT NULL,evidence_id text NOT NULL,contract_id text NOT NULL,ordinal bigint NOT NULL CHECK(ordinal>0 AND ordinal<=9007199254740991),payload_json text NOT NULL CHECK(payload_json IS JSON),PRIMARY KEY(tenant_id,scope_type,scope_id,connector_id,source_id,evidence_id),UNIQUE(tenant_id,scope_type,scope_id,connector_id,source_id,contract_id,ordinal),CONSTRAINT ext_evidence_contract_fk FOREIGN KEY(tenant_id,scope_type,scope_id,connector_id,source_id,contract_id) REFERENCES app_external_integration.ext_contracts(tenant_id,scope_type,scope_id,connector_id,source_id,contract_id) ON UPDATE NO ACTION ON DELETE NO ACTION);
CREATE FUNCTION app_external_integration.reject_append_only_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'append-only' USING ERRCODE='55000'; END $$;
CREATE TRIGGER ext_observations_append_only BEFORE UPDATE OR DELETE ON app_external_integration.ext_observations FOR EACH ROW EXECUTE FUNCTION app_external_integration.reject_append_only_mutation();
CREATE TRIGGER ext_evidence_append_only BEFORE UPDATE OR DELETE ON app_external_integration.ext_evidence FOR EACH ROW EXECUTE FUNCTION app_external_integration.reject_append_only_mutation();
COMMIT;
